"from PIL import Image\n\np4 = Image.open('page_previews/page-04.png')\nw, h = p4.size\n# Live2D is under Canva on the right column.\n# Let's crop the area around Live2D:\n# Canva was around x: 0.38*w to 0.46*w, y: 0.4*h to 0.52*h\n# Live2D should be below Canva around y: 0.54*h to 0.66*h, x: 0.38*w to 0.46*w\nlive2d_crop = p4.crop((int(w * 0.39), int(h * 0.54), int(w * 0.46), int(h * 0.66)))\nlive2d_crop.save('processed_assets/live2d_icon_raw.png')\nprint(\"Saved live2d_icon_raw.png\", live2d_crop.size)\n"